// Some portions generated by Codex
package org.eclipse.rdf4j.common.webapp;

import static org.assertj.core.api.Assertions.assertThatCode;

import org.eclipse.rdf4j.common.webapp.navigation.NavigationHandlerInterceptor;
import org.eclipse.rdf4j.common.webapp.navigation.NavigationModel;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

/**
 * {@code HandlerInterceptor.postHandle} receives a {@code null} {@code ModelAndView} whenever the handler already wrote
 * the response itself, which is what the extensionless JSON system endpoints such as {@code /system/lmdb/properties}
 * and {@code /system/breaker/status.view} do. The shared webapp interceptors are registered on those mappings, so they
 * must tolerate a {@code null} view instead of failing the request.
 */
class WebappHandlerInterceptorNullViewTest {

	private static final Object HANDLER = new Object();

	@Test
	void messageInterceptorToleratesNullModelAndView() {
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.getSession().setAttribute(Message.ATTRIBUTE_KEY, new Message(Message.Type.INFO, "boom"));

		assertThatCode(
				() -> new MessageHandlerInterceptor().postHandle(request, new MockHttpServletResponse(), HANDLER, null))
						.doesNotThrowAnyException();
	}

	@Test
	void commonValuesInterceptorToleratesNullModelAndView() {
		assertThatCode(() -> new CommonValuesHandlerInterceptor().postHandle(new MockHttpServletRequest(),
				new MockHttpServletResponse(), HANDLER, null)).doesNotThrowAnyException();
	}

	@Test
	void navigationInterceptorToleratesNullModelAndView() {
		NavigationHandlerInterceptor interceptor = new NavigationHandlerInterceptor();
		interceptor.setNavigationModel(new NavigationModel());

		assertThatCode(() -> interceptor.postHandle(new MockHttpServletRequest(), new MockHttpServletResponse(),
				HANDLER, null)).doesNotThrowAnyException();
	}
}
